-- Dumping data for table `posts`
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('1', '4', '1', 'SK Standar Pelayanan Publik', 'sk-standar-pelayanan-publik', 'Klik disini untuk melihat SK Standar Pelayanan Publliknya\n', '\n\n<div class=\"p-3 my-4 bg-white border border-primary-subtle rounded-3 shadow-sm d-flex align-items-center justify-content-between flex-wrap gap-3 reveal-scale\">\n    <div class=\"d-flex align-items-center gap-3\">\n        <div class=\"bg-primary text-white p-2 rounded-2 d-flex align-items-center justify-content-center\" style=\"width: 48px; height: 48px;\">\n            <i class=\"bi bi-file-earmark-pdf-fill fs-3\"></i>\n        </div>\n        <div>\n            <h6 class=\"fw-bold mb-1 text-dark\">SK Standar Pelayanan Publik</h6>\n            <small class=\"text-muted d-block\"><i class=\"bi bi-shield-check me-1 text-success\"></i> Dokumen Resmi Dinas Perhubungan Kab. Purbalingga</small>\n        </div>\n    </div>\n    <a href=\"/storage/documents/1785983104_xOQ29_SK-STANDAR-PELAYANAN-2026.pdf\" target=\"_blank\" class=\"btn btn-primary rounded-pill px-4 py-2 fw-semibold d-inline-flex align-items-center gap-2 shadow-sm\">\n        <i class=\"bi bi-eye\"></i> Lihat PDF\n    </a>\n</div>\n\n\n\n<p class=\"wp-block-paragraph\"></p>\n', 'posts/1785979707_mfKwxd_WhatsApp-Image-2026-07-21-at-09.25.50.webp', 'published', '0', '2026-07-13 09:59:10', 'SK Standar Pelayanan Publik', 'Klik disini untuk melihat SK Standar Pelayanan Publliknya\n', '2026-08-06 08:28:27', '2026-08-06 10:44:51', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('2', '4', '1', 'Layanan Pengaduan Dinas Perhubungan Kabupaten Purbalingga', 'layanan-pengaduan-dinas-perhubungan-kabupaten-purbalingga', '', '<p class=\"lead text-dark mb-4 lh-base font-medium\">\n    Dinas Perhubungan Kabupaten Purbalingga berkomitmen untuk menyelenggarakan pelayanan publik yang prima, transparan, dan akuntabel. Bagi masyarakat yang ingin menyampaikan pertanyaan, pengaduan, atau aspirasi terkait sarana dan prasarana transportasi, Dinas Perhubungan menyediakan berbagai saluran pengaduan resmi.\n</p>\n\n<p class=\"text-secondary lh-base mb-3\">\n    Masyarakat dapat memilih kanal layanan yang paling mudah dijangkau, baik melalui sistem online terpadu \"Tanya Dinhub\", pesan instan WhatsApp, email resmi, maupun datang langsung ke kantor Dinas Perhubungan Kabupaten Purbalingga pada jam operasional kerja.\n</p>\n\n<p class=\"text-secondary lh-base mb-3\">\n    Setiap laporan pengaduan yang masuk akan dicatat, ditelaah, dan ditindaklanjuti oleh petugas piket serta tim teknis bidang terkait secara profesional. Khusus untuk pengaduan darurat terkait Kerusakan Lampu Penerangan Jalan Umum (LPJU) yang berpotensi membahayakan keselamatan pengguna jalan di malam hari, penanganan dilakukan secara prioritas oleh tim siaga PJU.\n</p>\n\n<p class=\"text-secondary lh-base mb-0\">\n    Dengan adanya saluran pengaduan ini, diharapkan partisipasi aktif dari seluruh elemen masyarakat Purbalingga dalam mewujudkan keselamatan, ketertiban, dan kelancaran lalu lintas di Kabupaten Purbalingga.\n</p>', 'posts/1785979707_X9vBqJ_WhatsApp-Image-2026-07-08-at-14.08.28.webp', 'published', '0', '2026-07-08 14:26:39', 'Layanan Pengaduan Dinas Perhubungan Kabupaten Purbalingga', '', '2026-08-06 08:28:28', '2026-08-06 11:08:10', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('3', '4', '1', 'Nilai SKM Semester 1 Tahun 2026 Dinas Perhubungan kab.Purbalingga', 'nilai-skm-semester-1-tahun-2026-dinas-perhubungan-kab-purbalingga', '', '\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"841\" height=\"569\" src=\"/storage/posts/1785987091_y7wyh_WhatsApp-Image-2026-07-03-at-14.03.12.webp\" alt=\"\" class=\"wp-image-1610\" srcset=\"/storage/posts/1785987091_y7wyh_WhatsApp-Image-2026-07-03-at-14.03.12.webp 841w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2026/07/WhatsApp-Image-2026-07-03-at-14.03.12-300x203.jpeg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2026/07/WhatsApp-Image-2026-07-03-at-14.03.12-768x520.jpeg 768w\" sizes=\"auto, (max-width: 841px) 100vw, 841px\" /></figure>\n', 'posts/1785979708_xBXNBE_WhatsApp-Image-2026-07-21-at-08.28.02.webp', 'published', '0', '2026-07-06 09:24:54', 'Nilai SKM Semester 1 Tahun 2026 Dinas Perhubungan kab.Purbalingga', '', '2026-08-06 08:28:28', '2026-08-06 10:31:31', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('4', '4', '1', 'Nilai SKM Semester 2 Tahun 2025 Dinas Perhubungan kab. Purbalingga', 'nilai-skm-semester-2-tahun-2025-dinas-perhubungan-kab-purbalingga', '', '\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"658\" height=\"463\" src=\"/storage/posts/1785987091_3Cxn1_WhatsApp-Image-2026-07-03-at-14.03.13.webp\" alt=\"\" class=\"wp-image-1607\" srcset=\"/storage/posts/1785987091_3Cxn1_WhatsApp-Image-2026-07-03-at-14.03.13.webp 658w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2026/07/WhatsApp-Image-2026-07-03-at-14.03.13-300x211.jpeg 300w\" sizes=\"auto, (max-width: 658px) 100vw, 658px\" /></figure>\n', 'posts/1785979708_JhOlqK_WhatsApp-Image-2026-07-21-at-09.03.20.webp', 'published', '0', '2026-07-06 09:21:11', 'Nilai SKM Semester 2 Tahun 2025 Dinas Perhubungan kab. Purbalingga', '', '2026-08-06 08:28:28', '2026-08-06 10:31:31', NULL);
