INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('12', '2', '1', '<strong>Dinas Perhubungan Kabupaten Purbalingga Lakukan Pemeliharaan dan Perbaikan Lampu Penerangan Jalan Umum</strong>', 'dinas-perhubungan-kabupaten-purbalingga-lakukan-pemeliharaan-dan-perbaikan-lampu-penerangan-jalan-umum', 'Dinas Perhubungan Kabupaten Purbalingga melakukan pemeliharaan dan perbaikan lampu penerangan jalan umum di berbagai wilayah kabupaten. Kegiatan ini dilakukan untuk memastikan penerangan yang memadai...', '\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" src=\"/storage/posts/1785987092_O1srq_WhatsApp-Image-2023-03-27-at-14.08.47-768x1024.webp\" alt=\"\" class=\"wp-image-1231\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-27-at-14.08.47-768x1024.jpeg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-27-at-14.08.47-225x300.jpeg 225w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-27-at-14.08.47-1152x1536.jpeg 1152w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-27-at-14.08.47.jpeg 1200w\" sizes=\"auto, (max-width: 768px) 100vw, 768px\" /><figcaption class=\"wp-element-caption\"><em>Penanganan Housing Lepas Di Daerah Kec. Mrebet</em>.</figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Dinas Perhubungan Kabupaten Purbalingga melakukan pemeliharaan dan perbaikan lampu penerangan jalan umum di berbagai wilayah kabupaten. Kegiatan ini dilakukan untuk memastikan penerangan yang memadai bagi masyarakat yang beraktivitas pada malam hari terutama pada saat bulan ramadhan saat ini.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Perbaikan dan pemeliharaan ini menjadi prioritas utama Dinas Perhubungan untuk memberikan kenyamanan dan keamanan bagi warga yang beraktivitas pada malam hari. Dinas Perhubungan melakukan pemeliharaan dan perbaikan lampu penerangan jalan secara berkala dan terjadwal, sehingga masyarakat dapat merasa aman dan nyaman saat beraktivitas pada malam hari.</p>\n\n\n\n<figure class=\"wp-block-image size-large\"><img loading=\"lazy\" decoding=\"async\" width=\"768\" height=\"1024\" src=\"/storage/posts/1785987092_FAhPl_WhatsApp-Image-2023-03-27-at-14.10.57-1-768x1024.webp\" alt=\"\" class=\"wp-image-1233\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-27-at-14.10.57-1-768x1024.jpeg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-27-at-14.10.57-1-225x300.jpeg 225w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/WhatsApp-Image-2023-03-27-at-14.10.57-1.jpeg 960w\" sizes=\"auto, (max-width: 768px) 100vw, 768px\" /><figcaption class=\"wp-element-caption\"><em>Penyambungan Jaringan Putus Desa Krenceng.</em></figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Selain melakukan pemeliharaan dan perbaikan, Dinas Perhubungan juga mengganti lampu penerangan jalan yang sudah tidak berfungsi dengan lampu LED yang lebih hemat energi. Penggantian lampu penerangan jalan menjadi lampu LED selain dapat menghemat energi, juga dapat mengurangi biaya operasional serta memberikan penerangan yang lebih baik.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Dinas perhubungan berharap kegiatan pemeliharaan dan perbaikan ini dapat terus berjalan dengan lancar dan memberikan manfaat bagi masyarakat. Masyarakat juga diharapkan dapat turut berpartisipasi dalam menjaga keamanan dan kenyamanan lingkungan sekitar, termasuk dengan melaporkan apabila menemukan lampu penerangan jalan yang rusak atau mati.</p>\n', 'posts/1785979709_vzgIFf_WhatsApp-Image-2023-03-27-at-14.10.57-1.webp', 'published', '0', '2023-03-27 07:30:47', '<strong>Dinas Perhubungan Kabupaten Purbalingga Lakukan Pemeliharaan dan Perbaikan Lampu Penerangan Jalan Umum</strong>', 'Dinas Perhubungan Kabupaten Purbalingga melakukan pemeliharaan dan perbaikan lampu penerangan jalan umum di berbagai wilayah kabupaten. Kegiatan ini d...', '2026-08-06 08:28:30', '2026-08-06 10:31:33', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('13', '2', '1', 'Inspeksi Keselamatan pada Bus AKAP dan Pemeriksaan Laik Jalan Secara Fisual di Terminal Kota Purbalingga', 'inspeksi-keselamatan-pada-bus-akap-dan-pemeriksaan-laik-jalan-secara-fisual-di-terminal-kota-purbalingga', 'Purbalingga – Dinas Perhubungan Kabupaten Purbalingga dan Satuan Lalu Lintas POLRES Purbalingga melaksanakan inspeksi keselamatan sarana angkutan lebaran tahun 2023. Pemeriksaan dilakukan pada kendara...', '\n<p class=\"wp-block-paragraph\"></p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"1040\" height=\"780\" src=\"/storage/posts/1785987093_0rbWe_IMG-20230324-WA0012.webp\" alt=\"\" class=\"wp-image-1176\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/IMG-20230324-WA0012.jpg 1040w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/IMG-20230324-WA0012-300x225.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/IMG-20230324-WA0012-1024x768.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/IMG-20230324-WA0012-768x576.jpg 768w\" sizes=\"auto, (max-width: 1040px) 100vw, 1040px\" /><figcaption class=\"wp-element-caption\"><em>Inspeksi Keselamatan pada Bus AKAP dan Pemeriksaan Laik Jalan Secara Fisual di Terminal Kota Purbalingga</em> <em>Jumat (24/03/2023)</em></figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Purbalingga &#8211; Dinas Perhubungan Kabupaten Purbalingga dan Satuan Lalu Lintas POLRES Purbalingga melaksanakan inspeksi keselamatan sarana angkutan lebaran tahun 2023. Pemeriksaan dilakukan pada kendaraan bus AKAP yang beroperasi di Terminal Purbalingga guna memastikan kondisi laik jalan kendaraan.</p>\n\n\n\n<p class=\"wp-block-paragraph\">Dinas Perhubungan Kabupaten Purbalingga dan Satuan Lalu Lintas POLRES Purbalingga juga melakukan pemeriksaan dokumen serta laik jalan secara fisual pada kendaraan bus AKAP. Kegiatan ini merupakan langkah yang sangat penting untuk memastikan bahwa kendaraan yang beroperasi aman dan memenuhi persyaratan teknis yang ditetapkan oleh pemerintah.<br></p>\n\n\n\n<figure class=\"wp-block-image size-full\"><img loading=\"lazy\" decoding=\"async\" width=\"1040\" height=\"780\" src=\"/storage/posts/1785987093_Z1z0A_IMG-20230324-WA0011.webp\" alt=\"\" class=\"wp-image-1196\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/IMG-20230324-WA0011.jpg 1040w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/IMG-20230324-WA0011-300x225.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/IMG-20230324-WA0011-1024x768.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2023/03/IMG-20230324-WA0011-768x576.jpg 768w\" sizes=\"auto, (max-width: 1040px) 100vw, 1040px\" /><figcaption class=\"wp-element-caption\"><em>Inspeksi Keselamatan pada Bus AKAP dan Pemeriksaan Laik Jalan Secara Fisual di Terminal Kota Purbalingga</em> <em>Jumat (24/03/2023)</em></figcaption></figure>\n\n\n\n<p class=\"wp-block-paragraph\">Kegiatan inspeksi keselamatan lalu lintas dan angkutan jalan akan terus dilakukan Dinas Perhubungan Kabupaten Purbalingga dalam rangka mendukung transportasi yang selamat, aman dan nyaman. Dinas Perhubungan Kabupaten Purbalingga juga mengimbau kepada operator bus untuk selalu memperhatikan keamanan dan kenyamanan penumpang serta memastikan kendaraannya selalu dalam kondisi laik jalan dan siap operasi.</p>\n', 'posts/1785979710_nijAMm_IMG-20230324-WA0013.webp', 'published', '0', '2023-03-24 17:58:22', 'Inspeksi Keselamatan pada Bus AKAP dan Pemeriksaan Laik Jalan Secara Fisual di Terminal Kota Purbalingga', 'Purbalingga – Dinas Perhubungan Kabupaten Purbalingga dan Satuan Lalu Lintas POLRES Purbalingga melaksanakan inspeksi keselamatan sarana angkutan leba...', '2026-08-06 08:28:30', '2026-08-06 10:31:33', NULL);
