INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('27', '4', '1', 'BERITA HOAX HARGA TIKET PESAWAT KE PURBALINGGA', 'berita-hoax-harga-tiket-pesawat-ke-purbalingga', ' Masyarakat di Kabupaten Purbalingga dibuat heboh dengan beredarnya unggahan harga tiket penerbangan dari Jakarta-Purbalingga di platform media sosial Facebook, Senin (1/2). Dalam unggahan tersebut, s...', '<div><img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-423 alignleft\" src=\"/storage/posts/1785987096_bfZHO_WhatsApp-Image-2021-02-02-at-23.12.13-300x184.webp\" alt=\"\" width=\"300\" height=\"184\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2021/02/WhatsApp-Image-2021-02-02-at-23.12.13-300x184.jpeg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2021/02/WhatsApp-Image-2021-02-02-at-23.12.13.jpeg 706w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" /></div>\n<div>\n<div> Masyarakat di Kabupaten Purbalingga dibuat heboh dengan beredarnya unggahan harga tiket penerbangan dari Jakarta-Purbalingga di platform media sosial Facebook, Senin (1/2). Dalam unggahan tersebut, sejumlah maskapai penerbangan terlihat mencantumkan harga tiket, diantaranya Citilink, Air Asia, Lion, Batik Air, Wings Abadi Airlines, dan Garuda Indonesia.</div>\n<div>Dalam unggahan itu, tertulis harga tiket pesawat jurusan Jakarta-Purbalingga dengan harga mulai dari Rp 328.500 hingga Rp 1 jutaan. Berdasarkan penelusuran Radarmas, unggahan harga tiket tersebut diunggah oleh akun facebook Bekisar Merah.  Kepala Dinas Perhubungan Kabupaten Purbalingga Yani Sutrisno UN ketika dikonfirmasi mengaku kaget. Sebab, sepengetahuannya Bandara Jenderal Soedirman Purbaingga belum membuka atau meayani rute pesawat dari Jakarta ke Purbalingga atau jurusan manapun.</div>\n<div>“Kemarin (baru-baru ini, red), baru survei yang diakukan oleh Dirjen Perhubungan Udara Kemenhub. Nantinya masih akan dievaluasi apakah layak untuk melayani penerbangan atau tidak. Jika layak maka baru keluar izin operasional. Selanjutnya, baru ditawarkan rute ke Bandara Jenderal Soedirman oleh Kemenhub kepada maskapai,” jelasnya. Yani memastikan, beredarkan informasi harga tiket maskapai penerbangan dari Jakarta ke Purbalingga berita bohong (hoax). Hal itu diperkuat oleh perwakilan PT Angkasa Pura II di Purbalingga, selaku operator Bandara Jenderal Besar Soedirman. Sementara itu, berdasarkan penelusuran melalalui Google. Daftar harga tiket pesawat itu bukan rute Jakarta-Purbalingga. Tapi peringkat penawaran terbaik. Hasil pencarian google yang keluar ialah rute penerbangan dari Jakarta menuju bandara terdekat Kabupaten Purbalingga. Dalam hal ini, nama bandara yang muncul adalah Bandar Udara Internasional Yogyakarta (YIA). Sehingga unggahan tersebut tidak benar. Hal ini merupakan kesalahan mengartikan hasil pencarian google tentang harga tiket pesawat Jakarta-Purbalingga.</p>\n</div>\n</div>\n<div>\n</div>\n', NULL, 'published', '0', '2021-02-04 04:59:24', 'BERITA HOAX HARGA TIKET PESAWAT KE PURBALINGGA', ' Masyarakat di Kabupaten Purbalingga dibuat heboh dengan beredarnya unggahan harga tiket penerbangan dari Jakarta-Purbalingga di platform media sosial...', '2026-08-06 08:28:32', '2026-08-06 10:31:36', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('28', '4', '1', 'PELAKSANAAN KIR KENDARAAN SAAT PENDEMI COVID 19', 'pelaksanaan-kir-kendaraan-saat-pendemi-covid-19', '  Berdasarkan Surat Edaran Menteri Perhubungan Nomor : SE 11 Tahun 2020 Tentang Pedoman dan Petunjuk Teknis Penyelenggaraan Transportasi Darat Pada Masa Adaptasi Kebiasaan Baru untuk Mencegah Penyebar...', '<p>&nbsp;</p>\n<p><img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-401 alignright\" src=\"/storage/posts/1785987096_hdIQt_IMG-20200615-WA00211-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2020/06/IMG-20200615-WA00211-300x225.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2020/06/IMG-20200615-WA00211-768x577.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2020/06/IMG-20200615-WA00211-1024x769.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2020/06/IMG-20200615-WA00211.jpg 1156w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" /></p>\n<p>Berdasarkan Surat Edaran Menteri Perhubungan Nomor : SE 11 Tahun 2020 Tentang Pedoman dan Petunjuk Teknis Penyelenggaraan Transportasi Darat Pada Masa Adaptasi Kebiasaan Baru untuk Mencegah Penyebaran Corona Virus Disease 2019 (Covid 19), Dinas Perhubungan Kabupaten Purbalingga tetap melaksanakan pelayanan masyarakat Berupa Pengujian Kendaraan Bermotor, pelaksaan pengujian kendaraan bermotor dilaksanakan dengan penerapan protokol kesehatan baik petugas maupun pemohon uji kendaraan.</p>\n<p>Adapun Ketentuan Pemohon Uji Kendaraan diwajibkan sebagai berikut:</p>\n<ul>\n<li>Wajib Memakai Masker</li>\n<li>Wajib Memasuki bilik steril</li>\n<li>Wajib Mencuci Tangan dengan sabun dan air mengalir</li>\n<li>Wajib Cek Suhu badan</li>\n<li>Wajib Jaga jarak</li>\n<li>Kendaraan yang diuji wajib dalam kondisi bersih</li>\n<li style=\"text-align: left;\">Selain pengemudi tidak diperbolehkan masuk area pengujian kendaraan Bermotor</li>\n</ul>\n<p>untuk jadwal pelaksanaan Pengujian Kendaraan Bermotor adalah</p>\n<p>PENDAFTARAN jam 08.00 s.d 11.00 WIB</p>\n<p>PENGUJIAN KENDARAAN  jam 08.00 s.d 12.00 WIB</p>\n<p>Jumlah Kendaraan bermotor wajib uji dibatasi sebanyak 40 kendaraan per hari.  hal ini dimaksudkan agar tidak terjadi kerumunan dan sesuai dengan SE dari menteri Perhubungan.</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n', 'posts/1785979712_u9OAuF_WhatsApp-Image-2021-01-27-at-10.34.42.webp', 'published', '0', '2021-01-27 03:48:27', 'PELAKSANAAN KIR KENDARAAN SAAT PENDEMI COVID 19', '  Berdasarkan Surat Edaran Menteri Perhubungan Nomor : SE 11 Tahun 2020 Tentang Pedoman dan Petunjuk Teknis Penyelenggaraan Transportasi Darat Pada Ma...', '2026-08-06 08:28:32', '2026-08-06 10:31:36', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('29', '3', '1', 'Pembentukan Posko PPKM Tahap I 11 Januari – 25 Januari 2021', 'pembentukan-posko-ppkm-tahap-i-11-januari-25-januari-2021', 'Pembentukan Posko Perbatasan Pemberlakuan Pembatasan Kegiatan Masyarakat (PPKM) Tahap I tanggal 11 Januari 2021 s.d tanggal 25 Januari 2021 untuk informasi tersebut dapat kunjungi tautan berikut : htt...', '<p>Pembentukan Posko Perbatasan Pemberlakuan Pembatasan Kegiatan Masyarakat (PPKM) Tahap I tanggal 11 Januari 2021 s.d tanggal 25 Januari 2021</p>\n<p>untuk informasi tersebut dapat kunjungi tautan berikut :</p>\n<p>https://www.instagram.com/tv/CJ_Xdx1DSg3/?utm_medium=copy_link</p>\n', NULL, 'published', '0', '2021-01-13 08:32:25', 'Pembentukan Posko PPKM Tahap I 11 Januari – 25 Januari 2021', 'Pembentukan Posko Perbatasan Pemberlakuan Pembatasan Kegiatan Masyarakat (PPKM) Tahap I tanggal 11 Januari 2021 s.d tanggal 25 Januari 2021 untuk info...', '2026-08-06 08:28:32', '2026-08-06 08:28:32', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('30', '2', '1', 'Memasuki era New Normal, Dishub Purbalingga Batasi Uji KIR Kendaraan', 'memasuki-era-new-normal-dishub-purbalingga-batasi-ujia-kir-kendaraan', 'Memasuki Era New Normal, Dinas Perhubungan (Dishub) Kabupaten Purbalingga membatasi pelayanan Pengujian Kendaraan Bermotor (KIR) dengan alasan Dishub Kabupaten Purbalingga ingin menerapkan protokol ke...', '<p>Memasuki Era <em>New Normal,</em> Dinas Perhubungan (Dishub) Kabupaten Purbalingga membatasi pelayanan Pengujian Kendaraan Bermotor (KIR) dengan alasan Dishub Kabupaten Purbalingga ingin menerapkan protokol kesehatan di lingkungan kantor Dishub.</p>\n<p>Semula Kantor Dishub Kabupaten Purbalingga dapat melayani 70 kendaraan sekarang dibatasi hanya 25 kendaraan saja.</p>\n<p><img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-402 alignleft\" src=\"/storage/posts/1785987096_V4Udm_FIX-300x202.webp\" alt=\"\" width=\"300\" height=\"202\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2020/06/FIX-300x202.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2020/06/FIX-768x517.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2020/06/FIX-1024x690.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2020/06/FIX.jpg 1152w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" />Sopir atau masyarakat yang akan mendaftar untuk Uji KIR sebelumnya  wajib memakai masker, cuci tangan dengan sabun, dan melakukan jaga jarak atau <em>physical distancing</em>. Apabila ada masyarakat atau sopir yang akan melakukan pengujian KIR kendaraan tidak menggunakan masker maka tidak diperbolehkan untuk melakukan Uji KIR dan tidak dilayani. Masyarakat atau Sopir yang ingin melakukan pengujian sebelum masuk lingkungan kantor Dishub Kabupaten Purbalingga akan dilakukan pengecekan suhu dengan t<em>hermogun</em>, maksimal suhu tubuh yang diperbolehkan untuk  masuk adalah 37,5 derajat celcius. Kendaraan sebelum masuk gedung pengujian akan dilakukan penyemprotan disinfektan terlebih dahulu oleh petugas baru diperbolehkan untuk masuk.</p>\n<p>Untuk pelayanan pengujian kendaraan (KIR) Kabupaten Purbalingga dibatasi untuk hari Senin-Kamis buka pada jam 08.00 WIB dan tutup pendaftaran jam 11.00 WIB dan untuk Hari Jumat buka pada jam 08.00 WIB tutup jam 10.00 WIB. Dishub Kabupaten Purbalingga ingin menerapkan protokol kesehatan dengan ketat, agar di Kabupaten Purbalingga kasus penyebaran Covid-19 tidak semakin meningkat.</p>\n', NULL, 'published', '0', '2020-06-15 11:15:25', 'Memasuki era New Normal, Dishub Purbalingga Batasi Uji KIR Kendaraan', 'Memasuki Era New Normal, Dinas Perhubungan (Dishub) Kabupaten Purbalingga membatasi pelayanan Pengujian Kendaraan Bermotor (KIR) dengan alasan Dishub...', '2026-08-06 08:28:32', '2026-08-06 10:31:36', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('31', '4', '1', 'PEMBINAAN DAN PENERTIBAN PARKIR TEPI JALAN UMUM', 'pembinaan-dan-penertiban-parkir-tepi-jalan-umum', 'PEMBINAAN JURU PARKIR TEPI JALAN UMUM Dalam rangka pemenuhan target PAD dari sektor parkir tepi jalan umum Dinas Perhubungan beserta tim melakukan pembinaan dan penertiban kepad juru parkir tepi jalan...', '<p><strong>PEMBINAAN JURU PARKIR TEPI JALAN UMUM</strong></p>\n<p><img loading=\"lazy\" decoding=\"async\" class=\" wp-image-392 alignleft\" src=\"/storage/posts/1785987096_dX8I0_20190729_111351-300x146.webp\" alt=\"\" width=\"374\" height=\"182\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2019/07/20190729_111351-300x146.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2019/07/20190729_111351-768x373.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2019/07/20190729_111351-1024x498.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2019/07/20190729_111351-2000x972.jpg 2000w\" sizes=\"auto, (max-width: 374px) 100vw, 374px\" />Dalam rangka pemenuhan target PAD dari sektor parkir tepi jalan umum Dinas Perhubungan beserta tim melakukan pembinaan dan penertiban kepad juru parkir tepi jalan umum di wilayah Kec. Purbalingga. Senin (29/7).  Dinas Perhubungan Kab. Purbalingga ditarget PAD sebesar Rp. 2 M dari sektor parkir tepi jalan umum. sampai dengan bulan juli terealisasi sebesar Rp. 1 M atau baru 50 %, sehingga guna memenuhi target PAD Dinas perhubungan melakukan Pembinaan sekaligus penertiban terhadap juru parkir.</p>\n<p>Kepala Bidang Lalu Lintas Dinas Perhubungan Kab. Purbalingga Sunarto menjelaskan, Dinas Pehubungan beserta Tim yang meliputi TNI, Polri dan Satpol PP melakukan pembinaan sekaligus penertiban kepada juru parkir di wilayah Kec. Purbalingga, kegiatan ini kerap dilakukan untuk memacu semangat dan membina juru parkir. Dikatakan saat ini terdapat 360 juru parkir di Kabupaten Purbalingga, selain rutin kegiatan ini juga dilakukan secara insidentil dengan sidak. Ketika ditemukan pelanggaran di lapangan pihaknya langsung memberikan teguran baik ringan maupun berat seperti pencabutan surta tugas sebagai juru parkir. Kami optimis tahun ini target PAD dapat tercapai karena tahun 2018 dengan target PAD yang sama bisa tercapai sepenuhnya, &#8220;terang Sunarto&#8221;.</p>\n<p>Selain melakukan pembinaan Tim juga melakukan penertiban parkir tepi jalan umum, kendaraan yang masih parkir di trotoar untuk dipindahkan agar trotoar kembali ke fungsinya sebagai tempat pejalan kaki, hal ini di lakukan sepanjang Jalan Jendral Soedirman sampai dengan Jl DI Panjaitan. Semoga kedepan parkir tepi jalan umum di Kabupaten Purbalingga terlihat semakin rapi dan tertib dan target PAD dari sektor parkir tepi jalan umum selalu tercapai.</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n<p>&nbsp;</p>\n', 'posts/1785979712_bqgmgV_20190729_111351.webp', 'published', '0', '2019-07-31 01:56:55', 'PEMBINAAN DAN PENERTIBAN PARKIR TEPI JALAN UMUM', 'PEMBINAAN JURU PARKIR TEPI JALAN UMUM Dalam rangka pemenuhan target PAD dari sektor parkir tepi jalan umum Dinas Perhubungan beserta tim melakukan pem...', '2026-08-06 08:28:33', '2026-08-06 10:31:36', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('32', '4', '1', 'KESIAPAN JELANG ARUS MUDIK LEBARAN TAHUN 2019', 'kesiapan-jelang-arus-mudik-lebaran-tahun-2019', '  Dinas Perhubungan Kabupaten Purbalingga mulai melakukan penambahan rambu lalu lintas tambahan di sejumlah ruas jalan. ini dilakukan Dinas Perhubungan guna mempersiapkan jelang arus mudik Tahun 2019....', '<p>&nbsp;</p>\n<p><img loading=\"lazy\" decoding=\"async\" class=\" wp-image-340 alignleft\" src=\"/storage/posts/1785987096_C9Bv4_WhatsApp-Image-2019-05-20-at-12.49.52-300x169.webp\" alt=\"\" width=\"240\" height=\"135\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2019/05/WhatsApp-Image-2019-05-20-at-12.49.52-300x169.jpeg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2019/05/WhatsApp-Image-2019-05-20-at-12.49.52-768x432.jpeg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2019/05/WhatsApp-Image-2019-05-20-at-12.49.52-1024x577.jpeg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2019/05/WhatsApp-Image-2019-05-20-at-12.49.52.jpeg 1158w\" sizes=\"auto, (max-width: 240px) 100vw, 240px\" /></p>\n<p>Dinas Perhubungan Kabupaten Purbalingga mulai melakukan penambahan rambu lalu lintas tambahan di sejumlah ruas jalan. ini dilakukan Dinas Perhubungan guna mempersiapkan jelang arus mudik Tahun 2019. Dengan dibukanya exit tol Pemalang diperkirakan akan berdampak adanya peningkatan jumlah kendaraan yang akan melintas di jalur Pemalang Purbalingga.</p>\n<p>seperti diketahui bahwa jalur Pemalang Purbalingga ada beberapa titik rawan kecelakaan karena jalur ini kondisinya naik turun dan berkelok. salah satu titik rawan kecelakaan yaitu jalan raya Bayeman Desa Tlahab Lor Kecamatan Karangreja.</p>\n<p>Guna mengantisipasi hal tersebut maka Dinas Perhubungan Kabupaten Purbalingga terus melakukan persiapan-persiapan guna<br />\nmemperlancar arus mudik tahun ini. Persiapan tersebut antara lain dengan memperbaiki penerangan jalan, menambah rambu lalu<br />\nlintas tambahan di sejumlah ruas jalan, memasang spanduk peringatan di beberapa lokasi strategi termasuk di daerah rawan kecelakaan, mendirikan posko di beberapa lokasi. Menurut Kepala Dinas Perhubungan Yani Sutrisno, Penambahan rambu lalu lintas tersebut merupakan rambu penunjuk arah diletakan pada sejumlah ruas jalan sehingga diharapkan mampu memperlancar arus mudik dan balik lebaran.</p>\n<p>&nbsp;</p>\n', 'posts/1785979713_YUeM0f_WhatsApp-Image-2019-05-20-at-12.49.52.webp', 'published', '0', '2019-05-21 01:46:40', 'KESIAPAN JELANG ARUS MUDIK LEBARAN TAHUN 2019', '  Dinas Perhubungan Kabupaten Purbalingga mulai melakukan penambahan rambu lalu lintas tambahan di sejumlah ruas jalan. ini dilakukan Dinas Perhubunga...', '2026-08-06 08:28:33', '2026-08-06 10:31:36', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('33', '5', '1', 'I-K-U dishub 2018', 'i-k-u-dishub-2018', '', '<div class=\"ead-preview\"><div class=\"ead-document\" style=\"position: relative;padding-top: 90%;\"><iframe src=\"//view.officeapps.live.com/op/embed.aspx?src=http%3A%2F%2Fdishub.purbalinggakab.go.id%2Fwp-content%2Fuploads%2F2019%2F03%2FI-K-U-2018.doc\" title=\"Embedded Document\" class=\"ead-iframe\" style=\"width: 100%;height: 100%;border: none;position: absolute;left: 0;top: 0;\"></iframe></div><p class=\"embed_download\"><a href=\"http://dishub.purbalinggakab.go.id/wp-content/uploads/2019/03/I-K-U-2018.doc\" download>Download </a></p></div>\n', NULL, 'published', '0', '2019-03-26 07:04:55', 'I-K-U dishub 2018', '', '2026-08-06 08:28:33', '2026-08-06 08:28:33', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('34', '4', '1', 'PEMERINTAH KAB. PURBALINGGA DAPAT BANTUAN BUS SEKOLAH', 'pemerintah-kab-purbalingga-dapat-bantuan-bus-sekolah', 'Pemerintah Daerah Purbalingga melalui Dinas Perhubungan (dishub) menerima satu unit bus sekolah dari Direktorat Jenderal Perhubungan Darat Kementerian Perhubungan. Bus tersebut akan digunakan sebagai...', '<p><img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-266 alignleft\" src=\"/storage/posts/1785987096_hGhgI_bus-sekolah-1-300x169.webp\" alt=\"\" width=\"300\" height=\"169\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2018/12/bus-sekolah-1-300x169.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2018/12/bus-sekolah-1-768x432.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2018/12/bus-sekolah-1-1024x576.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2018/12/bus-sekolah-1.jpg 1280w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" />Pemerintah Daerah Purbalingga melalui Dinas Perhubungan (dishub) menerima satu unit bus sekolah dari Direktorat Jenderal Perhubungan Darat Kementerian Perhubungan. Bus tersebut akan digunakan sebagai angkutan perintis, untuk mengangkut siswa yang tempat tinggalnya belum dilalui angkutan umum.</p>\n<p>“Bus sekolah bantuan Kemenhub ini merupakan hasil pengajuan dari dishub Purbalingga dimana nanti pengoperasiannya mengutamakan pada jalur-jalur yang belum terlayani oleh angkutan umum,” kata Kepala Dinas Perhubungan Kab. Purbalingga R. Imam Wahyudi</p>\n<p>Pengajuan bus sekolah pada Kemenhub memang baru satu unit, hal ini dikarenakan bus sekolah masih dalam tahapan uji coba di Kabupaten Purbalingga. Oleh karena itu, akan segera disusun konsep sistem pengoperasiannya.</p>\n<p>“Sistem pengoperasian kan penting, sampai ke jalur, rute dan bagaimana subsidi dari Pemkab,” lanjutnya.</p>\n<p>Pengoperasional bus sekolah ini diharapkan dapat membantu utamanya siswa yang kurang mampu. Selain itu juga mengurangi pelanggaran yang dilakukan oleh pelajar yang belum waktunya untuk membawa sepeda motor.</p>\n<p>“Sehingga membiasakan pelajar untuk naik angkutan umum ke sekolah, dengan demikian bisa mengurangi kepadatan dan kemacetan lalu lintas di Purbalingga,” jelas Imam.</p>\n<p>Dalam rangka membangun sistem operasional bus sekolah, Imam menerangkan akan berkoordinasi dengan sekolah yang ada di Kabupaten Purbalingga. Untuk sementara ini, bus sekolah bantuan Kemenhub akan beroperasi di wilayah perkotaan.</p>\n<p>“Sementara ini belum bisa menjangkau wilayah terpencil masih melewati perkotaan, melihat ukurannya ini kan belum bisa ke desa-desa kalau desa barangkali modelnya atau nanti SOPnya itu akan beda,” ujarnya.</p>\n<p>Konsep rute yang akan dilalui oleb bus sekolah ini meliputi Terminal Jompo menyusur Jalan Sungkono, melewati Depan pasar Segamas, menuju Jalan Babakan atau Jalan Letnan Yusuf. Kemudian melewati perempatan Karangsentul ke kanan melalui SMA Negeri 1 Purbalingga sampai Alun-Alun Purbalingga.</p>\n<p>“Selanjutnya kita lewatkan bus sekolah ini ke jalan-jalan yang ada di situ yang terdapat sentra pendidikan, konsepnya seperti itu tapi untuk operasional sendiri nanti kami akan minta masukan dari Organda,” lanjut Imam.</p>\n<p>Fasilitas bus ini juga menurut Imam, cukup nyaman digunakan oleh pelajar yang ada di kabupaten Purbalingga. Fasilitas bus sendiri terdapat full AC, full Music kemudian ada sabuk pengaman di semua tempat duduknya.</p>\n<p>“Safety belt di semua tempat duduk dalam bus ini bisa dijadikan sebagai media pembelajaran juga bahwa naik mobil juga harus mengenakan sabuk pengaman,” tambahnya.</p>\n<p>Bus sekolah ini memiliki 26 tempat duduk, kemudian juga disediakan 10 pegangan yang dikhususkan bagi penumpang yang berdiri. Moda transportasi ini ditargetkan mulai beroperasi pada akhir Desember 2018.</p>\n', 'posts/1785979713_YNR1OU_bus-sekolah-1.webp', 'published', '0', '2018-12-13 05:21:15', 'PEMERINTAH KAB. PURBALINGGA DAPAT BANTUAN BUS SEKOLAH', 'Pemerintah Daerah Purbalingga melalui Dinas Perhubungan (dishub) menerima satu unit bus sekolah dari Direktorat Jenderal Perhubungan Darat Kementerian...', '2026-08-06 08:28:33', '2026-08-06 10:31:36', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('35', '4', '1', 'PERINGATAN HARI PERHUBUNGAN NASIONAL', 'peringatan-hari-perhubungan-nasional', 'Peringati Hari Perhubungan Nasional, dishub Purbalingga Tingkatkan Pelayanan Prima PURBALINGGA – Momentum peringatan Hari Perhubungan Nasional (Harhubnas) di jajaran Dinas Perhubungan Kabupaten Purbal...', '<figure id=\"attachment_178\" aria-describedby=\"caption-attachment-178\" style=\"width: 300px\" class=\"wp-caption alignleft\"><img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-178\" src=\"/storage/posts/1785987096_FVY1c_HR_20180921_083217-300x171.webp\" alt=\"\" width=\"300\" height=\"171\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2018/10/HR_20180921_083217-300x171.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2018/10/HR_20180921_083217-768x436.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2018/10/HR_20180921_083217-1024x582.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2018/10/HR_20180921_083217.jpg 1200w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" /><figcaption id=\"caption-attachment-178\" class=\"wp-caption-text\">PLT Bupati Purbalingga menyerahkan penghargaan kepada juru parkir teladan</figcaption></figure>\n<p><strong>Peringati Hari Perhubungan Nasional, dishub Purbalingga Tingkatkan Pelayanan Prima</strong></p>\n<p>PURBALINGGA – Momentum peringatan Hari Perhubungan Nasional (Harhubnas) di jajaran Dinas Perhubungan Kabupaten Purbalingga dijadikan tonggak peningkatan pelayanan prima kepad masyarakat. Hal itu ditandai dengan komitmen jajaran dishub untuk memberikan pelayanan “No Tip No Pungli”, Purbalingga Tanpa lampu Mati, serta penerapan Sistem Informasi Managemen Pengujian Kendaraan Bermotor (SIM PKB).</p>\n<p>“Komitmen kita terapkan pada seluruh pelayanan yang ada di dishub Purbalingga. Bahkan akan terus kita tingkatkan pada tahun-tahun berikutnya,” ujar Kepala Dinas Perhubungan R Imam Wahyudi di sela kegiatan Senam Bersama Plt Bupati Dyah Hayuning Pratiwi memperingati Harhubnas, Jumat (21/9).</p>\n<p>Imam Wahyudi menuturkan, pada 2018 ini unit Pengujian Kendaraan Bermotor  di kabupaten Purbalingga mendapat akreditasi B dimana di wilayah Barlingmascakeb hanya kabupaten Purbalingga dan Banjarnegara yang mendapatkan akreditasi B. “Dari 9 item alat uji yang seluruhnya menggunakan sistem komputerisasi, seluruhnya lulus akreditasi,” jelasnya.</p>\n<p>Dengan sistem itu, menurut Imam Wahyudi, penentuan lulus tidaknya proses pengujian kendaraan bermotor sudah tidak lagi dilakukan oleh manusia namun melalui sistem komputerisasi dari alat uji yang ada. Jika ada pemohon uji kir yang kendarraanya tidak lolos uji, pihaknya merekomendasikan untuk dilakukan service atau perbaikan pada benkel terstandar.</p>\n<p>“Tahun ini kita menerapkan SIM PKB dimana pembayaran retribusi PKB tidak lagi menggunakan uang tunai namun melalui pembayaran non tunai bekerjasama dengan Bank Jateng dan fasilitasi dari BI Purwokerto. Rencananya tahun depan kita tingkatkan dengan menggunakan smart card,” katanya.</p>\n<p>Inovasi lainnya, lanjut Imam Wahyudi, untuk pelayanan penyelenggaraan lampu penerangan jalan umum, pihaknya juga memberlakukan jargon Purbalingga Tanpa lampu Mati. Sayangnya untuk mewujudkan komitmen tersebut, perlu penambahan armada mobil pemeliharaan LPJU. Saat ini dari dua armada yang dimiliki, satu diantaranya dalam kondisi kurang baik.</p>\n<p>Melalui manageman pengelolaan parkir, pihaknya juga optimis penerimaan parkir kabupaten Purbalingga dari target Rp 2 miliar dapat tercapai. Saat ini dari pendapatan parkir tepi jalan umum sudah dapat disetor ke kas daerah mencapai Rp 1,5 miliar. Pihaknya juga tengah menyiapkan pelayanan ijin trayek untuk mengisi mall pelayananan yang tengah digagas pemkab Purbalingga.</p>\n<p>Pada kesempatan tersebut, Plt Bupati Dyah Hayuning Pratiwi, SE, BEcon, MM mengapresiasi berbagai prestasi yang dicapai dishub Purbalingga. Dirinya terus mendorong jajaran Dinas Perhubungan untuk terus meningkatkan pelayanan prima kepada masyarakat.</p>\n<p>“Saya minta jajaran dishub terus berbenah dengan melakukan evaluasi dan penentuan target kedepan lebih baik lagi. Selain itu, juga meningkatkan soliditas, keompakan dan keguyuban dengan membangun komitmen bersama dalam upaya memberikan manfaat yang lebih kepada masyarakat,” katanya.</p>\n<p>Selain itu, Plt Bupati juga mewanti-wanti agar jajaran dishub  senantiasa menerapkan tata kelola pemerintahan yang baik, tidak ada praktek korupsi, pungli dan gratifikasi. “Saya juga ingin penghargaan Wahana Tata Nugraha yang pernah diraih Purbalingga pada 2016 dapat kembali dipersembahkan sebagai salah satu pertanggungjawaban kinerja aparatur pemerintah,” tambahnya.</p>\n<p>Pada kesempatan tersebut, Plt Bupati Tiwi berkesempatan menyerahkan penghargaan Juru Parkir Terbaik masing-masing kepada Suwarsito, Agus Susanto, Ratno Santosa dan Slamet Purwito serta penghargaan Pramudi Terbaik kepada Sudenam.</p>\n<p>Selain senam bersama, peringatan Harhubnas juga diisi kegiatan anjangsana dan Ziarah makam Kepala dishub pertama era otonomi daerah yakni Almarhum Heru Prayitno, SH, Donor darah, bersih lingkungan dan pengumpulan bantuan rehab RTLH. (Hr/humas)</p>\n', 'posts/1785979713_NQdRsy_HR_20180921_083322.webp', 'published', '0', '2018-10-12 02:20:17', 'PERINGATAN HARI PERHUBUNGAN NASIONAL', 'Peringati Hari Perhubungan Nasional, dishub Purbalingga Tingkatkan Pelayanan Prima PURBALINGGA – Momentum peringatan Hari Perhubungan Nasional (Harhub...', '2026-08-06 08:28:33', '2026-08-06 10:31:36', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('36', '4', '1', 'GROUNDBREAKING BANDARA JEND. BESAR SOEDIRMAN DIJADWALKAN APRIL 2018', 'groundbreaking-bandara-jend-besar-soedirman-dijadwalkan-april-2018', 'Grounbreaking Pembangunan Bandara JBS Dijadwalkan April 2018 PURBALINGGA, INFO – Grounbreaking atau peletakan batu pertama pembangunan bandara Jenderal Besar Soedirman (JBS) dijadwalkan bulan April 20...', '<p class=\"yiv1012549148MsoNormal\"><i>Grounbreaking</i> Pembangunan Bandara JBS Dijadwalkan April 2018</p>\n<p class=\"yiv1012549148MsoNormal\">PURBALINGGA, INFO – <i>Grounbreaking</i> atau peletakan batu pertama pembangunan bandara Jenderal Besar Soedirman (JBS) dijadwalkan bulan April 2018 mendatang. Pihak Pemkab terus berkoordinasi dengan Pihak PT Angkasa Pura (AP) II di Jakarta. Groundbreaking ini menindaklanjuti atas nota kesepahaman atau <i>Memorandum of Understanding</i> (MoU) Pemkab Purbalingga dengan sejumpah pihak terkait, termasuk diantaranya PT Angkasa Pura II di Jakarta bulan November 2017 silam.</p>\n<p class=\"yiv1012549148MsoNormal\">            “Rencananya <i>grounbreaking</i> dimulainya pembangunan Bandara Jenderal Besar Soedirman akan dilakukan bulan April mendatang. Saat ini kami terus berkoordinasi dengan pemerintah pusat dan dengan PT Angkasa Pura II. Acara Grounbreaking dijadwalkan akan dihadiri Bapak Presiden ,” kata Bupati Purbalingga H Tasdi, SH, MM, pada saat menyampaikan pidato Laporan Keterangan Pertanggungjawaban (LKPJ) di ruang rapat paripurna DPRD setempat, Rabu (14/3).</p>\n<p class=\"yiv1012549148MsoNormal\">            Menyusul rencana pembangunan bandara itu, lanjut Bupati Tasdi, setidaknya sudah ada empat investor yang akan membangun sarana hotel di Purbalingga. Sejumlah hotel itu, yakni Bima Grand Hotel, Suit Garden Hotel, dan hotel Kokoria dan sebuah hotel bandara milik PT Angkasa Pura II,” kata Bupati Tasdi.</p>\n<p class=\"yiv1012549148MsoNormal\">            Seperti diberitakan sebelumnya, Pemkab Purbalingga telah menandatangani MoU terkait pembangunan bandara JBS. Para pihak yang menandatangani yakni Gubernur Jawa Tengah  H Ganjar Pranowo, SH, MIP, Direktur Utama PT Angkasa Pura (AP) II Muhammad Awaluddin, Asisten Logistik KSAU Marsekal Muda TNI Yadi Husyadi, dan Direktur Utama  LPPNPI (Lembaga Penyelenggara Pelayanan Navigasi Penerbangan Indonesia)/Airnav Indonesia, Novie Riyanto.</p>\n<p class=\"yiv1012549148MsoNormal\">            Penandatangan MoU antara Pemkab Purbalingga dengan berbagai pihak tersebut  menjadi catatan sejarah dimulainya realisasi pembangunan bandara Jenderal Besar Soedirman. Selanjutnya, PT Angkasa Pura II yang akan menjadi operator bandara JBS  mulai merealisasikan pembangunan fisik dengan finalisasi Detail Enginering Design (DED).</p>\n<p class=\"yiv1012549148MsoNormal\">            Sebelumnya, Markas besar TNI Angkatan Udara (Mabes TNI AU) telah memberikan ijin dan persetujuan kepada Pemkab Purbalingga yang membangun akses jalan menuju bandara JBS di wilayah Kemangkon. Lahan milik TNI AU yang akan dibangun akses jalan itu sepanjang 420 meter x 20 meter. Persetujuan itu terungkap dalam rapat yang digelar di oleh Tim Teknis Aset TNI AU.</p>\n<p class=\"yiv1012549148MsoNormal\">            Dalam kunjungan kerja Menteri Perhubungan Budi Karya Sumadi, bulan Agustus 2017 silam, telah diputuskan untuk pengembangan Lanud Jenderal Besar Soedirman (Wirasaba) menjadi bandara Jenderal Besar Soedirman. Pengelolaan bandara komersial itu nantinya dilakukan oleh PT AP II selaku operator. PT AP II menyiapkan anggaran Rp 350 miliar untuk membangun berbagai sarana prasarana pendukung seperti runway, taxiway, bangunan terminal seluas 3.000 meter persegi dan sarana lain. Untuk landasan pacu, dari sekarang 850 meter, akan diperpanjang menjadi 1.600 meter dengan lebar 30 meter. Tahap selanjutnya akan diperpanjang lagi menjadi 2.000 hingga 2.400 meter. (PI-1)</p>\n<p class=\"yiv1012549148MsoNormal\">\n', 'posts/1785979713_GBFJ8O_Menhub-ke-bandara-JBS.webp', 'published', '0', '2018-04-03 06:34:58', 'GROUNDBREAKING BANDARA JEND. BESAR SOEDIRMAN DIJADWALKAN APRIL 2018', 'Grounbreaking Pembangunan Bandara JBS Dijadwalkan April 2018 PURBALINGGA, INFO – Grounbreaking atau peletakan batu pertama pembangunan bandara Jendera...', '2026-08-06 08:28:33', '2026-08-06 09:54:47', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('37', '4', '1', 'PURBALINGGA BAKAL MEMPUNYAI BANDARA KOMERSIAL', 'purbalingga-bakal-mempunyai-bandara-komersial', 'Penandatangan Kesepahaman Pembangunan Bandara JBS Bupati Tasdi : Momentum Bersejarah dan Penting yang Lama Ditunggu PURBALINGGA, INFO – Bupati Purbalingga H Tasdi, SH, MM mengatakan, penandatanganan k...', '<hr />\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3811\" class=\"yiv2484900877MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3816\">Penandatangan Kesepahaman Pembangunan Bandara JBS</span></p>\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3815\" class=\"yiv2484900877MsoNormal\"><b id=\"yui_3_16_0_ym19_1_1510970362104_3814\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3813\">Bupati Tasdi : Momentum Bersejarah dan Penting yang Lama Ditunggu</span></b></p>\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3821\" class=\"yiv2484900877MsoNormal\"><b id=\"yui_3_16_0_ym19_1_1510970362104_3820\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3819\"><img loading=\"lazy\" decoding=\"async\" class=\"size-full wp-image-112 alignleft\" src=\"/storage/posts/1785987096_5lZGj_MOU.webp\" alt=\"\" width=\"150\" height=\"150\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/11/MOU.jpg 150w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/11/MOU-160x160.jpg 160w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/11/MOU-320x320.jpg 320w\" sizes=\"auto, (max-width: 150px) 100vw, 150px\" />PURBALINGGA, INFO – </span></b><span id=\"yui_3_16_0_ym19_1_1510970362104_3822\">Bupati Purbalingga H Tasdi, SH, MM mengatakan, penandatanganan kesepahaman bersama </span><span id=\"yui_3_16_0_ym19_1_1510970362104_3827\">tentang Pemanfaatan Barang Milik Negara dan Pengeleolaan Barang Milik Daerah di Kabupaten Purbalingga untuk Pengusahaan Bandar Udara Jenderal Besar Soedirman, merupakan momentum bersejarah dan penting yang telah lama ditunggu warga Purbalingga dan kabupaten di sekitarnya.</span></p>\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3829\" class=\"yiv2484900877MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3828\">            </span><span id=\"yui_3_16_0_ym19_1_1510970362104_3830\">“Dari sisi hari yaitu  hari Jum’at merupakan hari yang penuh berkah. Dari  sisi tanggal dan tahun yaitu tanggal 17  November tahun 2017 dapat dimaknai bahwa kita  mempunyai komitmen atau satu tujuan yang sama dalam rangka mengembangkan pangkalan udara  Jenderal Besar Soedirman menjadi bandara komersial guna mendukung perekonomian, perdagangan dan pariwisata serta melayani aksesibilitas masyarakat,” kata Bupati Tasdi, saat memberikan sambutan pada penanddatangan kesepahaman tersebut di Jakarta, Jum’at (17/11). </span></p>\n<p class=\"yiv2484900877MsoNormal\">            Penandatangan dilakukan oleh Bupati Purbalingga H Tasdi, SH, MM, Gubernur Jawa Tengah  H Ganjar Pranowo, SH, MIP, Direktur Utama PT Angkasa Pura (AP) II Muhammad Awaluddin, Asisten Logistik KSAU Marsekal Muda TNI Yadi Husyadi, dan Direktur Utama  LPPNPI (Lembaga Penyelenggara Pelayanan Navigasi Penerbangan Indonesia)/Airnav Indonesia, Novie Riyanto.</p>\n<p class=\"yiv2484900877MsoNormal\">            Ikut hadir menyaksikan penandatanganan itu Wakil Bupati Purbalingga Dyah Hayuning Pratiwi, SE, B.Econ, jajaran Forkompimda Purbalingga, para pejabat Purbalingga, Pemprov Jateng, pejabat dari Angkasa Pura II dan dari Airnav.</p>\n<p class=\"yiv2484900877MsoNormal\">            Tasdi mengatakan, Kabupaten Purbalingga menjadi bagian dari pulau Jawa dan berada disisi Jawa Tengah bagian Barat Selatan. Namun, untuk mencapainya butuh waktu yang lama. Jika naik pesawat dari Jakarta, harus ke Yogayakarta lebih dulu, jika naik kereta api juga butuh waktu yang lama. “Jangan sampai untuk mencapai wilayah Purbalingga dari Jakarta, terasa lebih jauh daripada ke Papua,” kata Tasdi sembari menambahkan rintisan bandara Soedirman mulai digagas sejak tahun 2006 sejak masa kepemimpinan Bupati Triyono Budi Sasongko.</p>\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3833\" class=\"yiv2484900877MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3832\">            Dalam kesempatan itu, Bupati Tasdi juga mengucapkan terima kasih kepada semua pihak, mulai dari Presiden Joko Widodo, Menteri Perhubungan dan jajarannya, Mabes TNI AU, Direktur Utama PT Angkasa Pura II beserta jajarannya, Airnav Indonesia, Gubernur Jawa Tengah dan semua pihak yang ikut mendukung terealisasinya bandara komersial Jenderal Besar Soedirman. “Saya juga meminta maaf kepada Pak Direktur Utama PT Angkasa Pura II, jika sering telepon menagih janji realisasi bandara Soedirman,” ujar Tasdi. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3835\" class=\"yiv2484900877MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3834\">            Pada kesempatan itu, Bupati Tasdi menyampaikan harapannya agar pembangunan fisik bandara Soedirman mulai dilaksanakan tanggal 18 Desember 2017, dan nantinya akan mulai digunakan satu tahun kemudian pada tanggal 18 Desember 2018. Tanggal 18 Desember merupakan hari jadi kabupaten Purbalingga,” kata Tasdi. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3837\" class=\"yiv2484900877MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3836\">            Sementara itu, Direktur Utama PT Angkasa Pura II Muhammad Awaluddin mengatakan, dengan ditandatanganinya kesepahaman bersama ini menggambarkan sinergi Indonesia yang baik. Awaluddin juga mengungkapkan, soal pembangunan bandara Jenderal Soedirman, beberapa kali ditanyakan Presiden kepada Menteri Perhubungan. Dan akhirnya hari ini menjadi memontum sejarah yang telah lama ditunggu. “Setelah penandatanganan kesepahaman ini, akan segera dituntaskan <i>Detail Enginering Design</i> (DED) serta disiapkan Perjanjian Kerjasamanya (PKS). PT Angkasa Pura II berkomitmen untuk mendukung aksesasibilitas di wilayah Jateng bagian Barat Selatan,” kata Muhhamad Awaluddin. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3839\" class=\"yiv2484900877MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3838\">            Gubernur Jateng Ganjar Pranowo menyatakan, dengan ditandatanganinya kesepahaman ini menandakan wujud nyata nasionalisme para pemangku kepentingan. Purbalingga, lanjut Ganjar Pranowo, merupakan tempat bersejarah lahirnya Jenderal Soedirman. Dulu untuk mencapai Purbalingga, butuh waktu lama. Jika naik pesawat dari jakarta ke Yogyakarta, dan masih harus menggunakan jalan darat. Jika naik kereta, juga butuh waktu lama, apalagi menggunakan jalan darat dari jakarta ke Purbalingga, bisa butuh waktu 10 jam.</span></p>\n<p id=\"yui_3_16_0_ym19_1_1510970362104_3840\" class=\"yiv2484900877MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1510970362104_3841\"> “Jika bandara Soedirman terwujud, maka akses menuju Purbalingga dan kota disekitarnya akan semakin terbuka lebar. Apalagi, Purbalingga merupakan kota yang menghasilkan bulu mata palsu. Banyak pabrik rambut dan bulu mata palsu yang dipakai oleh artis Holywood. Selain itu, dengan keberadaan bandara, juga akan membuka akses perdagangan, perekonomian dan pariwisata. Jika mau ke Dieng atau tempat wisata di Purbalingga atau sekitarnya, landing pesawatnya nanti cukup di Purbalingga,” kata Ganjar Pranowo. (PI-1/PI4).</span></p>\n', 'posts/1785979713_165ILn_MOI.webp', 'published', '0', '2017-11-18 02:12:16', 'PURBALINGGA BAKAL MEMPUNYAI BANDARA KOMERSIAL', 'Penandatangan Kesepahaman Pembangunan Bandara JBS Bupati Tasdi : Momentum Bersejarah dan Penting yang Lama Ditunggu PURBALINGGA, INFO – Bupati Purbali...', '2026-08-06 08:28:33', '2026-08-06 10:31:36', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('38', '5', '1', 'Mabes TNI AU Setujui Lahan untuk Akses Jalan Menuju Bandara Soedirman', 'mabes-tni-au-setujui-lahan-untuk-akses-jalan-menuju-bandara-soedirman', '  Mabes TNI AU Setujui Lahan untuk Akses Jalan Menuju Bandara Soedirman PURBALINGGA, INFO – Markas besar TNI Angkatan Udara (Mabes TNI AU) memberikan ijin dan persetujuan kepada Pemkab Purbalingga yan...', '<p>&nbsp;</p>\n<div id=\"yui_3_16_0_ym19_1_1502510446027_2265\" dir=\"ltr\">\n<p id=\"yui_3_16_0_ym19_1_1502510446027_2278\" class=\"yiv9453685720MsoNormal\"><b id=\"yui_3_16_0_ym19_1_1502510446027_2277\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2276\">Mabes TNI AU Setujui Lahan untuk Akses Jalan Menuju Bandara Soedirman</span></b></p>\n<p id=\"yui_3_16_0_ym19_1_1502510446027_2264\" class=\"yiv9453685720MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2263\">PURBALINGGA, INFO – Markas besar TNI Angkatan Udara (Mabes TNI AU) memberikan ijin dan persetujuan kepada Pemkab Purbalingga yang akan membangun akses jalan menuju Bandara Jenderal Besar Soedirman (BJBS) di wilayah Kemangkon. Lahan milik TNI AU yang akan dibangun akses jalan itu sepanjang 420 meter x 20 meter. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1502510446027_2272\" class=\"yiv9453685720MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2271\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2270\">            </span>Persetujuan itu terungkap dalam rapat yang digelar di oleh Tim Teknis Aset TNI AU di ruang Rapat Disfaskonau Gedung B2 Lantai 7 Mabes AU Jakarta, Kamis (10/8).  Rapat yang dipimpin oleh Kadisfaskonau Marsekal pertama TNI Ir Ruslan Efendi, M.Sc juga dihadiri Bupati Purbalingga H Tasdi, SH, MM.  Selain itu hadir juga Komandan Lanud Jenderal besar Soedirman Letkol Pnb Suparjo, ST, MM, Kasubdin Bin BTP Mabes TNI AU Kolonel Sus Tjoni Hendro Susanto, Kabag Perencanaan Dirjen Perhubungan Udara Kementerian perhubungan Syamsu Rizal, Kasubid Diseminasi Informasi Meteoroligi Penerbangan BMKG (Badan Meteorologi Klimatologi dan Geofisika), herlina, ST, Kepala Divisi Perencanaan dan Pengendalian Pelayanan Navigasi Penerbangan LPPNPI (Lembaga Penyelenggara Pelayanan Navigasi Penerbangan Indonesia)/Airnav Indonesia, Endaryono, dan Ketua Tim Rencana Kerjasama Pengelolaan dan Pengembangan Bandara Wilayah PT Angkasa Pura II (Persero), Deni Krisnowibowo. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1502510446027_2298\" class=\"yiv9453685720MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2297\">            Bupati Tasdi usai rapat mengatakan, rapat tersebut menghasilkan tiga poin yakni, Mabes TNI AU memberikan persetujuan penggunaan lahan untuk pembangunan akses jalan menuju bandara Jenderal Besar Soedirman. Akses jalan yang disetujui dengan ukuran panjang 420 meter dan lebar 20 meter. Detail lokasi itu akan dikoordinasikan antara Lanud Jenderal Besar Soedirman dengan PT Angkasa Pura II. Poin kedua, sesuai dengan surat Menteri Perhubungan RI nomor AU.101/3/17 PHB 2017 tertanggal 8 Agustus 2017 tentang Pengembangan Lanud Jenderal Besar Soedirman, intinya Menhub meminta kepada Menteri BUMN untuk menugaskan PT AP II guna membangun Bandara Jenderal Besar Soedirman.</span></p>\n<p id=\"yui_3_16_0_ym19_1_1502510446027_2300\" class=\"yiv9453685720MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2299\">            “Poin ketiga dalam rapat tersebut yakni akan disusun MoU atau pernyataan bersama tentang rencana pembangunan dan pengusahaan Bandara Jenderal Besar Soedirman antara TNI AU, pemprov Jateng, Pemkab Purbalingga, PT AP II, Airnav Indonesia dan BMKG,” kata Bupati Tasdi. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1502510446027_2302\" class=\"yiv9453685720MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2301\">            Seperti diberitakan sebelumnya, dalam kunjungan Menhub Budi Karya Sumadi, Minggu (6/8) lalu bersama Presiden Direktur PT AP II Muhammad Awaluddin, telah diputuskan untuk pengembangan Lanud Jenderal besar Soedirman (Wirasaba) menjadi bandara Jenderal Besar Soedirman. Pengelolaan bandara komersial itu nantinya dilakukan oleh PT AP II selaku operator. PT AP II telah menyiapkan anggaran Rp 350 miliar untuk membangun berbagai sarana prasarana pendukung seperti runway, taxiway, bangunan terminal seluas 3.000 meter persegi dan sarana lain. Untuk landasan pacu, dari sekarang 850 meter, akan diperpanjang menjadi 1.600 meter dengan lebar 30 meter. Tahap selanjutnya akan diperpanjang lagi menjadi 2.000 hingga 2.400 meter. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1502510446027_2304\" class=\"yiv9453685720MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2303\">            Tasdi menambahkan, rintisan pengembangan bandara Wirasaba menjadi bandara komersial dilakukan sejak tahun 2006 silam. Pengembangan landasan ini juga didukung oleh tujuh bupati disekitar wilayah Purbalingga.  Pemkab Purbalingga setidaknya telah melakukan 12 kali audiensi dengan Kemenhub untuk mematangkan realisasi bandara komersial Wirasaba, dan terakhir rapat di Mabes TNI AU. “Bandara Jenderal Besar Soedirman akan sangat mendukung pertumbuhan ekonomi dan pembangunan di wilayah Jawa Tengah bagian Selatan. Khusus untuk Purbalingga sendiri akan semakin memperkuat pergerakan investasi dan pariwisata. Di Purbalingga setidaknya ada 28 investor asing asal Korea, dan keberadaan bandara tentunya akan sangat mendukung investasi,” kata Tasdi. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1502510446027_2306\" class=\"yiv9453685720MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502510446027_2305\">            Tasdi menambahkan, pihaknya telah menyiapkan dana Rp 30 miliar untuk pembebasan lahan guna perluasan landasan pacu bandara. Selain itu juga membangun infrastruktur pendukung seperti pembangunan jembatan Linggamas yang mempersingkat jarak dari Purwokerto ke Bandara Wirasaba, pelebaran jalan akses menuju bandara,” kata Tasdi. (PI-1)</span></p>\n</div>\n', 'posts/1785979713_HeRL4V_IMG_7931.webp', 'published', '0', '2017-08-12 04:11:47', 'Mabes TNI AU Setujui Lahan untuk Akses Jalan Menuju Bandara Soedirman', '  Mabes TNI AU Setujui Lahan untuk Akses Jalan Menuju Bandara Soedirman PURBALINGGA, INFO – Markas besar TNI Angkatan Udara (Mabes TNI AU) memberikan...', '2026-08-06 08:28:33', '2026-08-06 09:54:47', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('39', '4', '1', 'Angkasa Pura II Siapkan Rp 350 Miliar', 'angkasa-pura-ii-siapkan-rp-350-miliar', 'Menhub : Bandara Jenderal Besar Soedirman Beroperasi Akhir 2018 PURBALINGGA, INFO – Menteri Perhubungan Budi Karya Sumadi memastikan bandar udara (bandara) Jenderal Besar Soedirman (BJBS) Purbalingga...', '<p id=\"yui_3_16_0_ym19_1_1502159427826_12683\" class=\"yiv3033174724MsoNormal\"><b id=\"yui_3_16_0_ym19_1_1502159427826_12687\"><span id=\"yui_3_16_0_ym19_1_1502159427826_12686\">Menhub : Bandara Jenderal Besar Soedirman Beroperasi Akhir 2018</span></b></p>\n<p id=\"yui_3_16_0_ym19_1_1502159427826_12685\" class=\"yiv3033174724MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502159427826_12684\">PURBALINGGA, INFO – Menteri Perhubungan Budi Karya Sumadi memastikan bandar udara (bandara) Jenderal Besar Soedirman (BJBS) Purbalingga akan beroperasi paling lambat akhir tahun 2018. PT Angkasa Pura (AP) II (Persero) akan menjadi operator atau pengelola bandara ini. PT Angkasa Pura II telah menyiapkan dana sebesar Rp 350 miliar untuk membangun prasarana pendukung. Sementara Pemkab Purbalingga diminta menyiapkan pembebasan lahan untuk perpanjangan landasan pacu dan pembenahan prasarana jalan menuju bandara. </span></p>\n<p id=\"yui_3_16_0_ym19_1_1502159427826_12699\" class=\"yiv3033174724MsoNormal\"><span id=\"yui_3_16_0_ym19_1_1502159427826_12698\"><span id=\"yui_3_16_0_ym19_1_1502159427826_12697\">            </span>Menhub memastikan hal tersebut saat melakukan kunjungan ke Bandara Jenderal Besar Soedirman, Minggu (6/8). Kedatangan Menhub Budi Karya Sumadi yang didampingi President Director PT Angkasa Pura II Muhammad Awaluddin, Dirjen Perhubungan udara Kemenhub Agus Santoso diterima oleh Bupati Purbalingga Tasdi, SH, MM, Ketua DPRD Purbalingga Tongat, SH, MM, jajaran Forkominda Purbalingga dan Tim Asset dari Mabes TNI AU. </span></p>\n<p class=\"yiv3033174724MsoNormal\">            “Dalam minggu ini kami akan memberikan surat persetujuan kepada Angkasa Pura II untuk mengelola Bandara Jenderal Besar Soedirman. Tembusan suratnya akan kami sampaikan juga ke Menteri BUMN, KSAU, Gubernur Jawa Tengah, dan Bupati Purbalingga. Karena asetnya milik TNI Angkatan Udara, maka AP II segera secara formalitas mengadakan perjanjian kerjasama dengan TNI AU dan juga dengan Pemkab Purbalingga,” kata Menhub Budi Karya Sumadi.</p>\n<p class=\"yiv3033174724MsoNormal\">            Dikatakan Menhub, target awal panjang landasan yang dibangun sepanjang 1.600 meter dengan lebar 30 meter. Ultimate panjang landasan nantinya sepanjang 2.000 atau 2.400 meter. Juga ada bangunan terminal seluas 3.000 meter persegi yang cukup untuk menampung 500.000 orang per tahun. “Diharapkan dengan dibangunnya Bandara Soedirman akan mempersingkat waktu tempuh. Biasanya ke Yogyakarta atau Semarang ditempuh lebih dari 4 jam, maka bisa ditempuh lebih singkat, kurang dari 2 jam, termasuk yang dari Cilacap,” kata Menhub.</p>\n<p class=\"yiv3033174724MsoNormal\">            Menhub juga optimis, pembangunan Bandara Soedirman akan memacu pertumbuhan ekonomi dan pertumbuhan sektor pariwisata di wilayah Jawa Tengah Bagian Selatan. “Ini kolaborasi yang sangat cantik antara AP II, Kemenhub, TNI AU dan Pemkab Purbalingga. Kami targetkan selesai pembangunan dan mulai dioperasikan akhir tahun 2018,” tegas Menhub Budi Karya Sumadi.</p>\n<p class=\"yiv3033174724MsoNormal\">            Sementara itu Presiden Director Angkasa Pura II Muhammad Awaluddin menambahkan, pihak AP II akan menyelesaian review Detail Enginering Desaign (DED) paling lama dua bulan. Ground Breaking bisa dilaksanakan pada sekitar Oktober – November 2017. Pihak AP II   akan menambah panjang lintasan dan pembangunan terminal. “AP II akan menyiapkan dana Rp 350 miliar untuk runway, taxiway dan fasilitas lain. “Untuk maskapai nanti terbuka bagi siapa saja, bisa Garuda, Lion dan maskapai nasional lainnya,” kata Muhammad Awaludin.</p>\n<p class=\"yiv3033174724MsoNormal\">            Bupati Purbalingga Tasdi, SH, MM mengatakan, rintisan pengembangan bandara Wirasaba menjadi bandara komersial dilakukan sejak tahun 2006 silam. Pengembangan landasan ini juga didukung oleh tujuh bupati disekitar wilayah Purbalingga.  Pemkab Purbalingga setidaknya telah melakukan 12 kali audiensi dengan Kemenhub untuk mematangkan realisasi bandara komersial Wirasaba. “Bandara Jenderal Besar Soedirman akan sangat mendukung pertumbuhan ekonomi dan pembangunan di wilayah Jawa Tengah bagian Selatan. Khusus untuk Purbalingga sendiri akan semakin memperkuat pergerakan investasi dan pariwisata. Di Purbalingga setidaknya ada 28 investor asing asal Korea, dan keberadaan bandara tentunya akan sangat mendukung investasi,” kata Tasdi.</p>\n<p class=\"yiv3033174724MsoNormal\">            Tasdi menambahkan, pihaknya telah menyiapkan dana Rp 30 miliar untuk pembebasan lahan guna perluasan landasan pacu bandara. Selain itu juga membangun infrastruktur pendukung seperti pembangunan jembatan Linggamas yang mempersingkat jarak dari Purwokerto ke Bandara Wirasaba, pelebaran jalan akses menuju bandara,” kata Tasdi. (PI-1/PI-3)</p>\n', 'posts/1785979713_a7syVK_menhub-ke-Purbalingga2.webp', 'published', '0', '2017-08-08 03:37:36', 'Angkasa Pura II Siapkan Rp 350 Miliar', 'Menhub : Bandara Jenderal Besar Soedirman Beroperasi Akhir 2018 PURBALINGGA, INFO – Menteri Perhubungan Budi Karya Sumadi memastikan bandar udara (ban...', '2026-08-06 08:28:34', '2026-08-06 09:54:48', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('40', '4', '1', 'BANDARA JENDRAL SOEDIRMAN BEROPERASI TAHUN 2018', 'bandara-jendral-soedirman-beroperasi-tahun-2018', '350 MILYAR UNTUK BANGUN BANDARA JENDRAL BESAR SOEDIRMAN PT Angkasa Pura II menyiapkan dana 350 Milyar guna membangun Bandar Udara Jendral Besar Soedirman. Bandar udara Jendral Besar Soedirman yang ter...', '<p>350 MILYAR UNTUK BANGUN BANDARA JENDRAL BESAR SOEDIRMAN</p>\n<p>PT Angkasa Pura II menyiapkan dana 350 Milyar guna membangun Bandar Udara<br />\nJendral Besar Soedirman. Bandar udara Jendral Besar Soedirman yang terletak<br />\ndi Desa  Wirasaba Kecamatan Bukateja Kabupaten Purbalingga yang dulunya bernama Landasan Udara Wirasaba akan berubah menjadi Bandara Komersial di Tahun 2018. Menurut Direktur Angkasa Pura II pihaknya telah menyiapkan dana guna pembangunan Bandara Jendral Besar Soedirman. Hal ini diungkapkan Direktur PT Angkasa Pura II saat Rapat Bersama Pemerintah Kabupaten Purbalingga dengan Kementrian Perhubungan disela-sela Acara Kunjungan Kerja Mentri Perhubungan RI-Bapak Budi Karya Sumadi.(6/8/2017)</p>\n<p>Pemerintah Kabupaten Purbalingga menyambut dengan senang dan bahagia karena sebentar lagi Kabupaten Purbalingga akan memiliki Bandar Udara komersial, Ungkap Bupati Purbalingga Tasdi. Menurutnya Rencana Pengembangan Bandar Udara Jendral Besar Soedirman yang dulunya bernama Lanud Wirasaba sejak Tahun 2006. Saat ini Pemerintah Kabupaten Purbalingga sedang tahap pembebasan lahan guna perluasan Bandara Jendral Besar Soedirman. Dengan dikembangkannya Bandara ini maka perekonomian kabupaten di Jawa Tengah Bagian Selatan  akan meningkat, juga sebagai pendukung kemajuan di Kabupaten Purbalingga pada khususnya dan Kabupaten-Kabupaten bagian selatan Jawa Tengah pada Umumnya.</p>\n<p>Mentri Perhubungan RI Bapak Budi Karya Sumadi menargetkan Bandara Udara<br />\nJendral Besar Soedirman beroperasi akhir tahun 2018.</p>\n', 'posts/1785979714_QCjiPk_IMG_7421.webp', 'published', '0', '2017-08-08 03:31:37', 'BANDARA JENDRAL SOEDIRMAN BEROPERASI TAHUN 2018', '350 MILYAR UNTUK BANGUN BANDARA JENDRAL BESAR SOEDIRMAN PT Angkasa Pura II menyiapkan dana 350 Milyar guna membangun Bandar Udara Jendral Besar Soedir...', '2026-08-06 08:28:34', '2026-08-06 09:55:09', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('41', '5', '1', 'PURBALINGGA MERAIH INAGARA AWARD 2017', 'purbalingga-meraih-inagara-award-2017', 'Terus Berinovasi, Purbalingga Terima Inagara Award 2017 PURBALINGGA, INFO – Bupati Purbalingga H Tasdi, SH, MM menerima penghargaan Inagara (Inovasi Administrasi Negara) Award tahun 2017. Penghargaan...', '<p>Terus Berinovasi, Purbalingga Terima Inagara Award 2017</p>\n<p>PURBALINGGA, INFO – Bupati Purbalingga H Tasdi, SH, MM menerima penghargaan Inagara (Inovasi Administrasi Negara) Award tahun 2017. Penghargaan Lembaga Administrasi Negara (LAN) ini diberikan pada para kepala daerah yang tanggap terhadap perubahan peradaban dunia dan mampu menciptakan inovasi di pemerintahan. Penghargaan diberikan oleh Kepala LAN, Drs Adi Suryanto, M.Si di gedung LAN Jakarta, Senin (7/8). Pemberian penghargaan disaksikan oleh Menteri ESDM, Ignasuis Jonan dan Menpan RB, Asman Abnur.</p>\n<p>Dengan diraihnya penghargaan itu,Bupati Tasdi dan wakil Bupati Dyah Hayuning Pratiwi, SE, B.Econ telah meraih sejumlah penghargaan baik skala regional maupun nasional.</p>\n<p>Khusus untuk penghargaan Inagara Award diberikan karena komitmen Bupati Tasdi terhadap perubahan dan inovasi yang tidak hanya dibidang fisik saja, tetapi komitmen untuk melakukan perubahan dan inovasi dibidang administrasi.</p>\n<p>“Kerja cerdas, kerja keras dan kerja ikhlas yang kita lakukan dengan seluruh jajaran Aparatur Sipil Negara serta dukungan masyarakat telah diakui secara nasional dengan diraihnya Ingara Award,” kata Tasdi, usai menerima penghargaan tersebut.</p>\n<p>Tasdi berharap, dengan diraihnya penghargaan Inagara Award akan menambah motivasi bagi Pemkab untuk senantiasa melakukan perubahan kearah perbaikan, “Dalam bidang layanan kepada masyarakat maupun bidang administrasi saat ini di Kabupaten Purbalingga sedang digagas sekitar 167 inovasi yang dilakukan oleh Organisasi Perangkat Daerah. Yang lebih penting, dari inovasi ini action-nya harus memberikan manfaat kepada masyarakat,” katanya.</p>\n<p>Sementara itu Kepala LAN RI Adi Suryanto mengatakan, penghargaan terhadap kepala daerah juga bertujuan untuk memotivasi daerah lain untuk berinovasi di bidang pelayanan publik. &#8220;Daerah yang mendapatkan penghargaan Inagara Award juga bisa menjadi rujukan bagi daerah lain untuk meniru atau replikasi inovasi-inovasinya. Apalagi penyelenggara layanan publik saat ini memang dituntut memberikan layanan prima untuk memberikan kepuasan kepada masyarakat,&#8221; ujarnya.</p>\n<p>LAN, tambah Adi Suryanto, terus mendorong setiap daerah di Indonesia untuk membuat inovasi karena sudah menjadi kewajiban dan keharusan dalam penyelenggaraan pemerintahan.</p>\n<p>Pada tahun 2017 ini, LAN memberikan Inagara Award kepada 15 daerah yang dianggap menunjukkan komitmennya yang kuat dan dukungan penuh dalam penyelenggaraan dan pelaksanaan inovasi di lingkungan pemerintahnya.</p>\n<p>Ke-15 daerah tersebut adalah Kabupaten Kudus, Kabupaten Banyumas, Kabupaten Sragen, dan Kabupaten Purbalingga, Kota Ambon, Kabupaten Tulungagung, Kota Solok, Kabupaten Bone, Kabupaten Banjar (Kalimantan Selatan), Kabupaten Bantul, Kota Tasikmalaya, Kabupaten Nunukan, Kabupaten Katingan, Kota Pontianak dan Provinsi Kalimantan Utara. (PI-1/PI-3)</p>\n', 'posts/1785979714_dqcn04_Inagara-award2.webp', 'published', '0', '2017-08-08 02:39:06', 'PURBALINGGA MERAIH INAGARA AWARD 2017', 'Terus Berinovasi, Purbalingga Terima Inagara Award 2017 PURBALINGGA, INFO – Bupati Purbalingga H Tasdi, SH, MM menerima penghargaan Inagara (Inovasi A...', '2026-08-06 08:28:34', '2026-08-06 09:55:09', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('42', '4', '1', 'RATUSAN PERANTAU ASAL PURBALINGGA IKUT MUDIK GRATIS', 'ratusan-perantau-asal-purbalingga-ikut-mudik-gratis', 'Sebanyak 350 perantau asal Purbalingga yang berada di Jakarta dan Sekitarnya Ikut dalam Mudik Gratis Tahun 2017. Acara yang diselenggarakan oleh Pemerintah Provinsi Jawa Tengah bekerjasama dengan Bank...', '<p style=\"text-align: left;\"><img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-82 alignleft\" src=\"/storage/posts/1785987096_wojlc_20170620_094720-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/20170620_094720-300x225.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/20170620_094720-768x576.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/20170620_094720-1024x768.jpg 1024w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" /> <img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-85 alignleft\" src=\"/storage/posts/1785987096_jPIQJ_20170620_101812-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/20170620_101812-300x225.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/20170620_101812-768x576.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/20170620_101812-1024x768.jpg 1024w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" /> Sebanyak 350 perantau asal Purbalingga yang berada di Jakarta dan Sekitarnya<br />\nIkut dalam Mudik Gratis Tahun 2017. Acara yang diselenggarakan oleh Pemerintah<br />\nProvinsi Jawa Tengah bekerjasama dengan Bank BPD Jawa Tengah diikuti ribuan perantau asal Jawa Tengah di Jakarta dan Sekitarnya. Pemerintah Kabupaten Purbalingga menyediakan tujuh unit Bus berkapasitas lima puluh tempat duduk.</p>\n<p style=\"text-align: left;\">Acara Mudik Gratis ini dilepas langsung oleh Gubernur Jawa Tengah, Ganjar Pranowo didampingi Pimpinan DPRD Jawa Tengah, Direktur Bank BPD Jawa Tengah dan Para Kepala Daerah di Jawa Tengah. Turut hadir Juga Kapolda Metro Jaya beserta jajarannya berlangsung di Taman Mini Indonesia Indah, (20/6/2017)</p>\n<p style=\"text-align: left;\">Kepala Dinas Perhubungan Kabupaten Purbalingga mengatakan bahwa Para Pemudik terbagi dalam tujuh unit Bus. &#8220;Tujuh unit bus tersebut terdiri dari satu unit dari Pemerintah Jawa Tengah, dua unit dari Bank BPD Jateng dan empat unit dari Pemerintah Kabupaten Purbalingga, dengan kapasitas masing-masing unit sebanyak lima puluh kursi&#8221;. terang Yonathan yang juga ikut dalam rombangan para pemudik, Selasa (20/6/2017).</p>\n<p style=\"text-align: left;\">&#8220;Pemerintah melalui Gubernur, Bupati dan walikota se-Jateng memberikan bantuan mudik gratis bertujuan untuk mengurangi pemudik yang menggunakan kendaraan pribadi yang bisa membahayakan pemudik&#8221; lanjut Yonathan.</p>\n<p style=\"text-align: left;\">Masyarakat sangat antusias dan senang dengan adanya mudik gratis yang difasilitasi oleh Pemerintah Kabupaten Purbalingga tiap tahunnya.</p>\n', 'posts/1785979715_tJzQw2_20170620_095537.webp', 'published', '0', '2017-06-21 06:06:37', 'RATUSAN PERANTAU ASAL PURBALINGGA IKUT MUDIK GRATIS', 'Sebanyak 350 perantau asal Purbalingga yang berada di Jakarta dan Sekitarnya Ikut dalam Mudik Gratis Tahun 2017. Acara yang diselenggarakan oleh Pemer...', '2026-08-06 08:28:35', '2026-08-06 10:31:37', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('43', '4', '1', 'PEMKAB PURBALINGGA SIAP MENYAMBUT PEMUDIK', 'pemkab-purbalingga-siap-menyambut-pemudik', 'Pemerintah Kabupaten (Pemkab) Purbalingga melalui Dinas Perhubungan (dishub) Purbalingga Jawa tengah siap menyambut para pemudik baik yang kembali maupun yang melintas melalui Kabupaten Purbalingga. “...', '<p style=\"text-align: left;\"><img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-69 alignleft\" src=\"/storage/posts/1785987097_A7Jgn_IMG-20170613-WA0031-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/IMG-20170613-WA0031-300x225.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/IMG-20170613-WA0031-768x576.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/IMG-20170613-WA0031-1024x768.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/06/IMG-20170613-WA0031.jpg 1080w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" />Pemerintah Kabupaten (Pemkab) Purbalingga melalui Dinas Perhubungan (dishub) Purbalingga  Jawa tengah siap menyambut para pemudik baik yang kembali maupun yang melintas melalui Kabupaten Purbalingga.</p>\n<p style=\"text-align: left;\">&#8220;Berbagai persiapan telah dilaksanakan oleh Dinas Perhubungan baik pada ruas jalan utama maupun jalan alternatif melalui penambahan sarana prasarana dan perlengkapan jalan guna menunjang keselamatan para pemudik yang melintas melalui Kabupaten Purbalingga. Penambahan itu meliputi traffic light, warning light, rambu penunjuk arah portable serta perbaikan Lampu Penerangan Jalan Umum yang mati. Selain itu pihak Dinas Perhubungan juga telah melakukan koordinasi kesiapan terminal-terminal  yang menjadi kewenangan Pemerintah Kabupaten Purbalingga pada H-7 dan H+7 &#8221; hal ini disampaikan kepala Dinas Perhubungan Kabupaten Purbalingga Yonathan Eko Nugroho (13/06/2017).</p>\n<p style=\"text-align: left;\">Yonathan juga mengatakan bahwa seluruh jajaran Dinas Perhubungan Kabupaten Purbalingga siap memberikan pelayanan dan pengamanan pada masa mudik dan balik Lebaran Tahun 2017. Hal ini dilakukan dengan cara menyiapkan Posko Pengamanan Lebaran Di Bayeman Desa Tlahab Lor Kec. Karangreja dimana jalur tersebut merupakan jalur yang perlu perhatian khusus. Pendirian Posko Pengamanan telah dikoordinasikan dengan instansi terkait.</p>\n<p style=\"text-align: left;\">Sementara itu untuk fasilitas penunjang seperti Rest area diterminal dan posko kesehatan serta uji kalaikan Angkutan Mudik Lebaran juga akan disiapkan denga berkoordinasi dengan instansi terkait.</p>\n', 'posts/1785979715_DJBccZ_IMG-20170613-WA0031.webp', 'published', '0', '2017-06-14 01:40:06', 'PEMKAB PURBALINGGA SIAP MENYAMBUT PEMUDIK', 'Pemerintah Kabupaten (Pemkab) Purbalingga melalui Dinas Perhubungan (dishub) Purbalingga Jawa tengah siap menyambut para pemudik baik yang kembali mau...', '2026-08-06 08:28:35', '2026-08-06 10:31:37', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('44', '4', '1', 'Pengembangan Bandar Udara Jendral Besar Soedirman', 'pengembangan-bandar-udara-jendral-besar-soedirman', 'Angkasa Pura II Tangani Pembangunan Bandar Udara Jendral Soedirman. Pengembangan Bandar Udara Jendral Besar Soedirman segera terwujud, Bandar Udara Jendral Besar Soedirman yang dulunya Bandar Udara Wi...', '<p>Angkasa Pura II Tangani Pembangunan Bandar Udara Jendral Soedirman.</p>\n<p>Pengembangan Bandar Udara Jendral Besar Soedirman segera terwujud, Bandar Udara Jendral Besar Soedirman yang dulunya Bandar Udara Wirasaba akan dikembangkan menjadi Bandar Udara Komersial. Pembangunan ditangani oleh pihak Angkasa Pura II. Bandar Udara yang terletak di Desa Wirasaba Kecamatan Bukateja yang saat ini sebagai pangkalan udara TNI Angakatan Udara.</p>\n<p>Jumat 21 April 2017 Tim dari Angkasa Pura meninjau langsung Bandar Udara Jendral Besar Soedirman di Wirasaba Purbalingga, Tim yang terdiri dari 3 (tiga) orang dan dipimpin oleh Deni (Angkasa Pura II) didampingi dari Kementrian Perhubungan dan Dinas Perhubungan Provinsi Jawa Tengah diterima langsung oleh Komandan Landasan Udara Jendral Besar Soedirman serta Kepala Dinas Perhubungan Kabupaten Purbalingga beserta jajarannya.</p>\n<p>Pelaksanaan tinjauan langsung ke Bandar Udara Jendral Besar Soedirman menindaklajuti perintah dua Menteri yakni Menteri BUMN dan Menteri Perhubungan ujar Deni yang disampaikan oleh Drs. Yonathan EKo N, M.Hum saat apel Pagi di Dinas Perhubungan (22/4).</p>\n', NULL, 'published', '0', '2017-04-22 04:58:25', 'Pengembangan Bandar Udara Jendral Besar Soedirman', 'Angkasa Pura II Tangani Pembangunan Bandar Udara Jendral Soedirman. Pengembangan Bandar Udara Jendral Besar Soedirman segera terwujud, Bandar Udara Je...', '2026-08-06 08:28:35', '2026-08-06 08:28:35', NULL);
INSERT INTO `posts` (`id`, `post_category_id`, `user_id`, `title`, `slug`, `excerpt`, `content`, `thumbnail`, `status`, `is_headline`, `published_at`, `meta_title`, `meta_description`, `created_at`, `updated_at`, `deleted_at`) VALUES ('45', '4', '1', 'Pemerintah Kabupaten Purbalingga Mendapat Bantuan Gubernur Sebesar 21   Milyar', 'pemerintah-kabupaten-purbalingga-mendapat-bantuan-gubernur-sebesar-21-milyar', 'Survei pemasangan LPJU Tenaga Surya Ruas Jalan Selaganggeng-Kutabawa Pemerintah Kabupaten Purbalingga Mendapat Bantuan Gubernur Sebesar Rp 21 Milyar, bantuan Pembangunan Lampu Penerangan Jalan Umum Te...', '<p>Survei pemasangan LPJU Tenaga Surya Ruas Jalan Selaganggeng-Kutabawa<img loading=\"lazy\" decoding=\"async\" class=\"size-medium wp-image-23 alignleft\" src=\"/storage/posts/1785987097_7azES_Jl-selagangeng-Serang-300x225.webp\" alt=\"\" width=\"300\" height=\"225\" srcset=\"https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/04/Jl-selagangeng-Serang-300x225.jpg 300w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/04/Jl-selagangeng-Serang-768x576.jpg 768w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/04/Jl-selagangeng-Serang-1024x768.jpg 1024w, https://dishub.purbalinggakab.go.id/wp-content/uploads/2017/04/Jl-selagangeng-Serang-2000x1500.jpg 2000w\" sizes=\"auto, (max-width: 300px) 100vw, 300px\" /></p>\n<p style=\"text-align: left;\">Pemerintah Kabupaten Purbalingga Mendapat Bantuan Gubernur Sebesar Rp 21 Milyar, bantuan Pembangunan Lampu Penerangan Jalan Umum Tenaga surya(LPJU) Tahun 2017. LPJU tenaga Surya tersebut akan segera terpasang di tujuh ruas jalan kabupaten Purbalingga. Tujuh ruas jalan tersebut adalah Ruas jalan Bobotsari-Rembang, Ruas Jalan Selaganggeng-Kutabawa, Ruas Jalan Karangreja-Kutabawa, Ruas Jalan Karangreja-Karangjambu, Ruas Jalan Rembang-Pengadegan, Ruas Jalan Purbalingga-pagembrungan, dan ruas jalan Purbalingga-Tobong.</p>\n<p style=\"text-align: left;\">&#8220;tujuh ruas jalan yang mendapatkan bantuan saat ini belum terpasang Lampu Penerangan Jalan Umum Tenaga Surya&#8221; tutur Sumarno Kasi LPJU Dinas Perhubungan Kab. Purbalingga.</p>\n<p style=\"text-align: left;\">Pemasangan LPJU tenaga surya dimaksudkan agar para pengendara lebih nyaman dalam berkendara pada malam hari dan mengurangi angka kecelakaan Lalu lintas. Selain itu untuk ruas jalan Selanggangeng-Kutabawa merupakan jalur alternatif menuju Desa Wisata Serang, juga sebagai jalur evakuasi.</p>\n<p style=\"text-align: left;\">Jumlah LPJU Tenaga Surya yang akan segera terpasang sebanyak 506 titik . Bupati Purbalingga mengharapkan saat lebaran Tahun 2017 minimal 50 % titik LPJU dapat terpasang dan menyala sehingga Purbalingga tambah terang benderang.</p>\n<p><a href=\"https://edusmart.smadajo.sch.id/berita/detail/cara-menggugurkan-kandungan/\">Cara Menggugurkan Kandungan</a>, <a href=\"https://opendata.pa-pangkalpinang.go.id/\">obat aborsi</a>, <a href=\"https://rsud.pa-pangkalpinang.go.id/\">cytotec</a></p>\n', 'posts/1785979715_P8CABM_Jl-selagangeng-Serang.webp', 'published', '0', '2017-04-20 04:52:07', 'Pemerintah Kabupaten Purbalingga Mendapat Bantuan Gubernur Sebesar 21   Milyar', 'Survei pemasangan LPJU Tenaga Surya Ruas Jalan Selaganggeng-Kutabawa Pemerintah Kabupaten Purbalingga Mendapat Bantuan Gubernur Sebesar Rp 21 Milyar,...', '2026-08-06 08:28:35', '2026-08-06 10:31:37', NULL);

